mapper.select:
SELECT k.KEYWORD_ID, k.KEYWORD_NAME, SUM(kds.DAILY_COUNT) as total_mentions, COUNT(DISTINCT kds.STATS_DATE) as mention_days FROM KEYWORD k LEFT JOIN KEYWORD_DAILY_STATS kds ON k.KEYWORD_ID = kds.KEYWORD_ID WHERE k.KEYWORD_ID IN
#{id}
AND k.KEYWORD_ID != 0 GROUP BY k.KEYWORD_ID, k.KEYWORD_NAME ORDER BY total_mentions DESC NULLS LAST

SELECT EMOTIONS AS LABEL, SOURCE_ID FROM ( -- YouTube 댓글의 감정 데이터 SELECT yc.EMOTIONS, yc.COMMENT_ID AS SOURCE_ID FROM YOUTUBE_COMMENT yc JOIN YOUTUBE_VIDEO yv ON yc.VIDEO_ID = yv.VIDEO_ID WHERE yv.KEYWORD_ID = #{keywordId} AND yc.EMOTIONS IS NOT NULL AND yc.EMOTIONS != '[]' AND yc.EMOTIONS != '["없음"]' AND yc.EMOTIONS != '["분석실패"]' AND yc.EMOTIONS != '["분석불가"]'
AND yc.PUBLISHED_AT >= ADD_MONTHS(#{lastMentionDate, jdbcType=DATE}, -3) AND yc.PUBLISHED_AT <= #{lastMentionDate, jdbcType=DATE}
UNION ALL
-- Instagram 댓글의 감정 데이터 (COMMENT_ID를 문자열로 변환) SELECT ic.EMOTIONS, TO_CHAR(ic.COMMENT_ID) AS SOURCE_ID FROM INSTAGRAM_COMMENT ic JOIN INSTAGRAM_POST ip ON ic.POST_ID = ip.POST_ID WHERE ip.KEYWORD_ID = #{keywordId} AND ic.EMOTIONS IS NOT NULL AND ic.EMOTIONS != '[]' AND ic.EMOTIONS != '["없음"]' AND ic.EMOTIONS != '["분석실패"]' AND ic.EMOTIONS != '["분석불가"]'
AND ic.COMMENT_DATE >= ADD_MONTHS(#{lastMentionDate, jdbcType=DATE}, -3) AND ic.COMMENT_DATE <= #{lastMentionDate, jdbcType=DATE}
) WHERE EMOTIONS IS NOT NULL
